/**
 * Starts the visit of a new stack map frame, stored in  {@link #currentFrame}.
 * @param offset   the bytecode offset of the instruction to which the frame corresponds.
 * @param numLocal the number of local variables in the frame.
 * @param numStack the number of stack elements in the frame.
 * @return the index of the next element to be written in this frame.
 */
int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // create a new stack map frame and set its metadata
    currentFrame = new StackMapFrame(numLocal, numStack);
    currentFrame.setOffset(offset);

    // set the base slot numbers for local and stack variables
    int localBaseSlot = currentFrame.getLocalCount();
    int stackBaseSlot = currentFrame.getStackCount();

    // initialize the slots for local variables
    for (int i = 0; i < numLocal; i++) {
        currentFrame.setLocal(localBaseSlot++, new StackMapFrame.Item());
    }

    // initialize the slots for stack variables
    for (int i = 0; i < numStack; i++) {
        currentFrame.setStack(stackBaseSlot++, new StackMapFrame.Item());
    }

    // return the index of the next element to be written in this frame
    return localBaseSlot + stackBaseSlot - 1;
}

