    if (this.capacity - this.used < size) {
        // Calculate the new capacity based on the current size and the amount of space needed
        int newCapacity = this.used + size;
        // Create a new array of the appropriate size
        byte[] newArray = new byte[newCapacity];
        // Copy the elements from the old array to the new array
        System.arraycopy(this.array, 0, newArray, 0, this.used);
        // Update the reference to the array
        this.array = newArray;
        // Update the capacity
        this.capacity = newCapacity;
    }
