public Mappings diffStructure(String tableName, Mappings mappings) {
    // Filter out _source config
    Mappings filteredMappings = new Mappings(tableName, mappings.getMappings().getProperties());

    // Get all field names from input mappings
    Set<String> inputFieldNames = new HashSet<>(filteredMappings.getMappings().keySet());

    // Get all field names from history mappings
    Set<String> historicalFieldNames = new HashSet<>(mappings.getMappings().keySet());

    // Return mappings with fields that do not exist in input mappings
    Mappings nonExistentMappings = new Mappings(tableName,
        filteredMappings.getMappings().keySet().stream()
            .filter(fieldName -> !inputFieldNames.contains(fieldName))
            .collect(Collectors.toSet()));

    return nonExistentMappings;
}
