static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = (timeBucket / 100000000) * 100000000;
    long month = (timeBucket / 1000000 - year * 100) * 100;
    long day = (timeBucket / 100 - year * 10000 - month * 100) * 100;
    long hour = (timeBucket / 100 - year * 10000 - month * 100 - day * 100) * 100;
    long minute = (timeBucket / 10 - year * 1000000 - month * 100000 - day * 10000 - hour * 1000) * 100;
    long second = (timeBucket - year * 100000000 - month * 10000000 - day * 1000000 - hour * 100000 - minute * 1000);

    int step = dayStep / 10;
    int remaining = dayStep % 10;

    long newYear = year + step * 100000000;
    long newMonth = month + step * 100;
    long newDay = day + step * 100;
    long newHour = hour + step * 100;
    long newMinute = minute + step * 100;
    long newSecond = second + remaining;

    return newYear * 100000000 + newMonth * 1000000 + newDay * 100000 + newHour * 10000 + newMinute * 1000 + newSecond;
}
