package com.kony.internal;

public class CompressTimeBucket{
    /** 
     * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
     */
    public static long compressTimeBucket(long timeBucket, int dayStep) {
        long recalculatedTimeBucket = timeBucket;
        for (int i = 0; i < dayStep; i++) {
            recalculatedTimeBucket = recalculatedTimeBucket - 2;
            if (recalculatedTimeBucket < 0) {
                recalculatedTimeBucket = recalculatedTimeBucket + 31;
            }
        }
        return recalculatedTimeBucket;
    }
}

package Main;

/**
 * Follow the dayStep to re-format the time bucket literal long value.
 * Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101,
 * 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted
 * time bucket is 20000123
 */
public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the number of days in the time bucket
    int numDays = (int) timeBucket / 10000;

    // Calculate the number of days to skip
    int numDaysToSkip = dayStep - 1;

    // Calculate the new day value
    int newDay = (numDays + numDaysToSkip) % 10;

    // Generate the new time bucket
    return (newDay * 10000) + timeBucket;
}
}

