public static StackMapFrame createStackMapFrame(List<StackMapType> stackMapTableEntries, int start, int end) {
    for (int i = start; i < end; i++) {
        StackMapType type = stackMapTableEntries.get(i);
        switch (type) {
            case AbstractObject:
                stackMapTableEntries.set(i, StackMapType.AbstractObject);
                break;
            case AbstractValue:
                stackMapTableEntries.set(i, StackMapType.AbstractValue);
                break;
            case Double:
                stackMapTableEntries.set(i, StackMapType.Double);
                break;
            case Float:
                stackMapTableEntries.set(i, StackMapType.Float);
                break;
            case Long:
                stackMapTableEntries.set(i, StackMapType.Long);
                break;
            case Integer:
                stackMapTableEntries.set(i, StackMapType.Integer);
                break;
            case Null:
                stackMapTableEntries.set(i, StackMapType.Null);
                break;
            case InitializedObject:
                stackMapTableEntries.set(i, StackMapType.InitializedObject);
                break;
            case UninitializedObject:
                stackMapTableEntries.set(i, StackMapType.UninitializedObject);
                break;
            default:
                throw new IllegalArgumentException("Unknown stack map type: " + type.name());
        }
    }

    return new StackMapFrame(stackMapTableEntries);
}

