    }

    return path;
}

/// <summary>
/// Transform from a Set representation to a graph path.
/// </summary>
/// <param name="tour">A set containing the edges of the tour</param>
/// <param name="graph">The graph</param>
/// <returns>A graph path</returns>
protected GraphPath<V, E> EdgeSetToTour(Set<E> tour, Graph<V, E> graph)
{
    List<E> edges = new List<E>(tour);
    List<V> vertices = new List<V>();

    foreach (E edge in edges)
    {
        vertices.Add(graph.getEndpointA(edge));
        vertices.Add(graph.getEndpointB(edge));
    }

    vertices.RemoveLast();
    return new GraphPath<V, E>(graph, vertices);
}

