public static boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if all vertices are connected
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    // Check if the complement of the given vertices are disconnected
    for (V vertex : graph.vertexSet()) {
        if (!vertices.contains(vertex)) {
            for (V neighbor : graph.neighborSet(vertex)) {
                if (vertices.contains(neighbor)) {
                    return false;
                }
            }
        }
    }

    return true;
}

