public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    int lastSeparatorIndex = path.lastIndexOf("/");
    if (lastSeparatorIndex == -1) {
        throw new IllegalArgumentException("Path does not contain any separators");
    }

    String parentPath = path.substring(0, lastSeparatorIndex);
    String fileName = path.substring(lastSeparatorIndex + 1);
    String[] relativePathComponents = relativePath.split("/");

    StringBuilder fullPath = new StringBuilder();
    fullPath.append(parentPath);
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // Do nothing
        } else if (component.equals("..")) {
            int newLastSeparatorIndex = parentPath.lastIndexOf("/");
            if (newLastSeparatorIndex == -1) {
                throw new IllegalArgumentException("Attempting to go above root");
            }
            parentPath = parentPath.substring(0, newLastSeparatorIndex);
        } else {
            if (fullPath.length() > 0) {
                fullPath.append("/");
            }
            fullPath.append(component);
        }
    }
    fullPath.append("/");
    fullPath.append(fileName);

    return fullPath.toString();
}

